    const TokenVoiceChoice* tokenVoiceChoice(
        data::BoardEdition edition, TokenVoiceLine line,
        std::uint8_t token) noexcept
    {
        const auto lineIndex = static_cast<std::size_t>(line);
        if (lineIndex >= LineCount || token >= TokenVoiceTokenCount)
            return nullptr;
        const auto& table = edition == data::BoardEdition::Europe
            ? EuropeVoices : UsaVoices;
        return &table[lineIndex][token];
    }

    std::optional<data::DataId> chooseTokenVoice(
        data::BoardEdition edition, TokenVoiceLine line,
        std::uint8_t token, std::uint32_t randomValue) noexcept
    {
        const auto* choice = tokenVoiceChoice(edition, line, token);
        if (choice == nullptr || choice->firstTag == 0 ||
            choice->alternateCount == 0)
            return std::nullopt;
        const auto tag = static_cast<data::DataTag>(
            choice->firstTag + (randomValue % choice->alternateCount));
        return data::packDataId(data::LegacyGroupId::LanguageDialog, tag);
    }
